mapper.select:


    mp.status = 'ACTIVE'
    and screen.status = 'ACTIVE'

        and mp.target_type = #{criteria.targetType}


        and mp.target_id = #{criteria.targetId}


        and mp.access_allowed = #{criteria.accessAllowed}


        and (screen.menu_name ilike concat('%', #{criteria.filter}, '%')
            or screen.screen_id ilike concat('%', #{criteria.filter}, '%')
            or screen.url ilike concat('%', #{criteria.filter}, '%'))


order by coalesce(top.display_order, middle.display_order, screen.display_order),
         coalesce(middle.display_order, screen.display_order),
         screen.display_order,
         screen.menu_id
limit #{criteria.safeSize} offset #{criteria.offset}

select count(*) from menu_permissions mp join menus screen on screen.menu_id = mp.menu_id
mp.status = 'ACTIVE' and screen.status = 'ACTIVE'
and mp.target_type = #{criteria.targetType}
and mp.target_id = #{criteria.targetId}
and mp.access_allowed = #{criteria.accessAllowed}
and (screen.menu_name ilike concat('%', #{criteria.filter}, '%') or screen.screen_id ilike concat('%', #{criteria.filter}, '%') or screen.url ilike concat('%', #{criteria.filter}, '%'))


where mp.target_type = #{targetType}
  and mp.target_id = #{targetId}
  and mp.menu_id = #{menuId}
  and mp.status = 'ACTIVE'
